    private val byNation = pools.associateBy { it.nation }
    private val foreignPools = pools.filter { it.weight > 0 }
    private val totalWeight = foreignPools.sumOf { it.weight }

    fun pool(nation: String): Pool? = byNation[nation]

    /** Ağırlığa göre rastgele yabancı uyruk. */
    fun randomForeign(rnd: Random, exclude: String): Pool {
        repeat(4) {
            var x = rnd.nextInt(totalWeight)
            for (p in foreignPools) {
                x -= p.weight
                if (x < 0) { if (p.nation != exclude) return p; break }
            }
        }
        return foreignPools.first { it.nation != exclude }
    }

    fun name(pool: Pool, rnd: Random): String {
        repeat(8) {
            val n = "${pool.first.random(rnd)} ${pool.last.random(rnd)}"
            if (n !in blocked) return n
        }
        return "${pool.first.random(rnd)} ${pool.last.random(rnd)}"
    }

    fun isBlocked(name: String) = name in blocked
}
